(() => {
  'use strict';
  const $ = s => document.querySelector(s);
  const e = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const button = (text,action,cls='',attrs='') => `<button class="button ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
  const badge = (text,tone='neutral') => `<span class="badge ${tone}">${e(text)}</span>`;
  const progress = n => `<div class="progress"><span style="width:${n}%"></span></div>`;
  const statusLabel = s => ({running:'运行中',pending:'等待取消确认',cancelled:'已取消',queued:'排队中',completed:'已完成',review:'待审核'}[s]||s);
  const initialSessions = [
    {id:'optimize',title:'长尾场景优化',summary:'训练与业务评测 · 14:32',context:{tab:'runs',object:'train',sub:'metrics'},kind:'optimize'},
    {id:'data',title:'构建售后数据集',summary:'数据质量与样本审核 · 13:40',context:{tab:'assets',object:'data',sub:'recipe'},kind:'data'},
    {id:'explore',title:'下一轮研究方向',summary:'研究假设与实验计划 · 昨天',context:{tab:'plan',object:'plan',sub:''},kind:'explore'}
  ];
  const state = {
    current:'optimize',sessions:initialSessions.map(s=>({...s,engine:'Codex',messages:[],draft:'',refs:[],pending:false})),engine:'Codex',connected:true,
    inspector:{tab:'runs',object:'train',sub:'metrics',pin:false,owner:'optimize'},rightOpen:true,width:window.innerWidth>=1650?430:390,
    train:{status:'running',step:1200},eval:{scored:760},plan:{budget:2,goal:'提升物流异常场景的业务通过率',submitted:false},
    sample:{status:'待修正',answer:'退款一定会在两小时内到账。'},retry:false,datasetVersion:3,extras:[],extensions:{data:true,training:true,mcp:false},
    events:[{time:'14:32',text:'Run-042 保存 checkpoint-1200，完整训练状态已持久化。',object:'train'},{time:'14:30',text:'Eval-018 已完成 760 / 1,000 条评分，当前为阶段结果。',object:'eval'},{time:'14:28',text:'Data-019 分片 17 超时，断点已保存。',object:'data'}],timers:{}
  };
  const session = () => state.sessions.find(s=>s.id===state.current);
  const refNames={train:'Run-042 · 训练观测',data:'Data-019 · 数据配方',eval:'Eval-018 · 评测证据',plan:'Plan-003 · 下一轮计划',config:'train.yaml · 配置',report:'eval-report.md · 评测报告',model:'售后模型 v3 · 权重血缘'};
  function showToast(text) { $('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(state.toast);state.toast=setTimeout(()=>$('#toast').classList.remove('show'),3500); }
  function modal(title,body,actions='') { const d=$('#modal');if(d.open)d.close();d.innerHTML=`<div class="modal-head"><div><span class="eyebrow">WORKSPACE ACTION · 演示</span><h2>${title}</h2></div><button class="icon-button" data-action="close" aria-label="关闭弹窗">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-foot">${actions}</div>`:''}`;d.showModal(); }
  const close = () => {if($('#modal').open)$('#modal').close();};
  function event(text,object='train') {state.events.unshift({time:'刚刚',text,object});}
  function saveDraft(){session().draft=$('#prompt').value;}
  function selectSession(id) {
    if(!state.sessions.some(s=>s.id===id))return;
    saveDraft(); state.current=id;
    if(!state.inspector.pin){state.inspector={...state.inspector,...session().context,owner:id};}
    $('#app').classList.remove('mobile-left');if(window.innerWidth<=1050)$('#inspector').classList.remove('mobile-open');render();
  }
  function openObject(object,sub='') {
    const tab=object==='plan'?'plan':['train','eval','tasks','extra'].includes(object)?'runs':'assets';
    state.inspector={...state.inspector,tab,object,sub:sub||(object==='train'?'metrics':object==='data'?'recipe':''),owner:state.current};
    session().context={tab,object,sub:state.inspector.sub};showRight();renderInspector();
  }
  function showRight(){state.rightOpen=true;$('#app').classList.remove('right-hidden');$('#app').classList.remove('mobile-left');$('#inspector').classList.add('mobile-open');$('.workbench-toggle').setAttribute('aria-expanded','true');}
  function renderSidebar(){
    $('#sessions').innerHTML=state.sessions.map(s=>`<button class="session ${s.id===state.current?'active':''}" data-action="session" data-id="${s.id}" ${s.id===state.current?'aria-current="page"':''}><span class="session-icon">${s.id==='optimize'?'◈':'◷'}</span><span class="session-text"><strong>${e(s.title)}</strong><small>${e(s.pending?'Agent 正在回复…':s.summary)}</small></span>${s.id==='optimize'&&state.train.status==='running'?'<span class="status-dot green"></span>':''}</button>`).join('');
    $('#resources').innerHTML=[['data','▤','数据与配方','v'+state.datasetVersion],['train','⌁','训练实验','Run-042'],['eval','☷','评测与报告','Eval-018'],['model','◇','模型与产物','v3']].map(([id,ic,title,count])=>`<button class="resource-link" data-action="object" data-object="${id}"><span class="resource-icon">${ic}</span><span>${title}</span><span>${count}</span></button>`).join('');
  }
  function toolsCard() { return `<details class="tool-group"><summary><span>已检查数据、训练与评测记录</span><span>3 项工具活动 ✓</span></summary><div class="tool-item"><span>✓</span><span>读取数据质量摘要</span><code>data.inspect / Data-019</code><button data-action="object" data-object="data">查看输出 ↗</button></div><div class="tool-item"><span>✓</span><span>查询远端训练状态</span><code>runner.status / job_042</code><button data-action="object" data-object="train">查看输出 ↗</button></div><div class="tool-item"><span>✓</span><span>读取评测切片</span><code>eval.slices / Eval-018</code><button data-action="object" data-object="eval">查看输出 ↗</button></div></details>`; }
  function trainCard(){return `<div class="action-card"><div class="card-head"><div class="card-title"><span class="card-icon">⌁</span><strong>长尾样本增强实验</strong></div>${badge(statusLabel(state.train.status),state.train.status==='running'?'green':state.train.status==='pending'?'amber':'neutral')}</div><div class="card-body"><div class="metric-row"><div><small>训练步数</small><strong>${state.train.step.toLocaleString()}<small>/ 3,000</small></strong></div><div><small>最近损失</small><strong>0.842</strong></div><div><small>验证通过率</small><strong>82.6<small>%</small></strong></div></div>${progress(state.train.step/30)}<div class="run-strip"><span class="status-dot ${state.connected?'green':'amber'}"></span>${state.connected?'模拟快照 · 14:32:08':'连接中断 · 最后观测 14:32:08，数据已过期'}</div></div><div class="card-foot"><span>Run-042 · gpu-a100-01 · LoRA SFT</span><div class="row">${button('日志','inspect-logs')}${button('打开监控 ↗','object','', 'data-object="train"')}</div></div></div>`;}
  function planCard(){return `<div class="action-card"><div class="card-head"><div class="card-title"><span class="card-icon">☷</span><strong>下一轮验证计划</strong></div>${badge(state.plan.submitted?'已提交':'草稿',state.plan.submitted?'green':'neutral')}</div><div class="card-body"><div class="plan-step"><span>1</span><div>审计物流异常业务规则，确认缺失的边界条件</div></div><div class="plan-step"><span>2</span><div>使用业务资料构建 300 条训练侧样本</div></div><div class="plan-step"><span>3</span><div>固定独立评测集，对比长尾采样权重</div></div></div><div class="card-foot"><span>${state.plan.budget} GPU·h 预算 · 评测集 v2 独立锁定</span><div class="row">${button('调整计划','object','', 'data-object="plan"')}${button(state.plan.submitted?'查看任务':'提交演示任务',state.plan.submitted?'tasks':'execute-plan','primary')}</div></div></div>`;}
  function dataCard(){return `<div class="action-card"><div class="card-head"><div class="card-title"><span class="card-icon">▤</span><strong>售后数据集构建</strong></div>${badge(state.sample.status==='待修正'?'需要审核':'审核已处理',state.sample.status==='待修正'?'amber':'green')}</div><div class="card-body"><p class="message-text">原始 28,640 条 → 清洗与去重 → 长尾增强 → 人工复核。<br>样本 S-0283 存在无依据的退款时限承诺，暂未加入冻结版本。</p></div><div class="card-foot"><span>Data-019 · 配方 r7 · 输入来源可追溯</span><div class="row">${button('查看配方','object','', 'data-object="data"')}${button('审核样本 ↗','sample','primary')}</div></div></div>`;}
  function agentMessage(body,meta='已完成本轮回复',refs=[],engine=session().engine||'Codex') {return `<article class="message"><div class="message-meta"><span class="agent-avatar">✳</span>TrainerBuddy <small>${e(engine)} · ${meta}</small></div><div class="message-text">${body}</div>${refs.length?`<div class="reply-refs">${refs.map(r=>`<button data-action="object" data-object="${r}">↗ ${refNames[r]||e(r)}</button>`).join('')}</div>`:''}</article>`;}
  function initialConversation(s){
    if(s.kind==='new')return `<div class="empty-state"><span class="agent-avatar">✳</span><h2>你想让模型解决什么问题？</h2><p>带着目标开始，Agent 会和你一起补齐数据、评测与执行路径。</p><div class="mode-grid">${[['我有模型和评测集','优化指标或验证训练策略'],['我有少量业务数据','先定义如何判断效果'],['我只有业务要求','从场景与业务基线开始'],['我想探索研究方向','提出假设，设计最小实验']].map(([title,desc])=>`<button class="mode-button" data-action="starter" data-text="${title}"><strong>${title} ↗</strong><small>${desc}</small></button>`).join('')}</div></div>`;
    if(s.kind==='data')return `<div class="date-marker">今天 · 数据构建会话</div><div class="message-user">我有一批售后工单和少量业务知识，请帮我构建可用于微调的数据集，并检查质量。</div>${agentMessage('<p>我会先预览字段和来源，再生成可重试的数据配方。<strong>原始数据、处理过程与最终版本分别保存。</strong></p>'+dataCard()+'<p>当前有一条样本需要人工核对。你可以在右侧修改答案、通过或排除；这些操作会记录到本轮数据审计。</p>','数据审计已完成',['data'])}`;
    if(s.kind==='explore')return `<div class="date-marker">开放研究 · 不需要复现目标</div><div class="message-user">如果不限定论文复现，我们还能从哪些方向提升售后模型的业务表现？</div>${agentMessage('<p>可以先验证三个假设：<strong>业务规则是否缺失、长尾样本是否不足、政策知识是否更适合通过检索补充。</strong></p><p>建议只改变一个变量，先小规模验证。下面是一个可调整的训练实验计划，也可以继续讨论检索方案。</p>'+planCard(),'研究计划草稿',['plan','eval'])}`;
    return `<div class="date-marker">今天 · 第三轮业务优化</div><div class="message-user">继续优化售后模型，重点看物流异常和退换货场景。帮我看看这轮训练的进展，再判断下一步怎么做。</div>${agentMessage('<p>我已经检查了这轮数据、训练和阶段评测。<strong>训练仍在运行，验证通过率为 82.6%</strong>，但物流异常切片仍有差距。</p>'+toolsCard()+trainCard()+'<p>建议先完成样本审核，等独立评测结束后再决定下一轮。右侧已打开训练观测，你可以继续与我讨论，不必离开当前对话。</p><div class="question"><strong>待判断 · 退款时效的表述</strong><p>1 条样本承诺“两小时到账”，业务资料未提供该依据。</p><div class="row">'+button('在右侧审核','sample')+button('先分析评测差距','inspect-eval','text')+'</div></div>','基于项目记录',['data','eval'])}`;
  }
  function renderCenter(scrollBottom=false){
    const s=session(),scroll=$('#message-scroll'),position=scroll.scrollTop;
    $('#conversation-title').textContent=s.title;$('#session-breadcrumb').textContent=s.title;
    $('#conversation-subtitle').textContent=s.kind==='new'?'目标、计划、工具调用与结果，都在同一个会话中推进。':'售后服务模型 · 项目会话 · 任务与会话分别管理';
    $('#messages').innerHTML=initialConversation(s)+s.messages.map(m=>m.role==='user'?`<div class="message-user">${m.refs.length?`<div class="reply-refs">${m.refs.map(r=>badge(refNames[r]||r)).join('')}</div>`:''}${e(m.text).replace(/\n/g,'<br>')}</div>`:agentMessage(`<p>${e(m.text).replace(/\n/g,'<br>')}</p>${m.card==='plan'?planCard():m.card==='train'?trainCard():m.card==='data'?dataCard():''}`,'演示回复',m.refs,m.engine||s.engine)).join('')+(s.pending?agentMessage('<p>正在整理当前任务与证据…</p>','模拟生成中',[],s.pendingEngine):'');
    $('#prompt').value=s.draft;$('#engine-name').textContent=state.engine;
    $('.send-button').textContent=s.pending?'■':'↑';$('.send-button').setAttribute('aria-label',s.pending?'停止 Agent 回复':'发送给 Agent');
    $('#agent-status').innerHTML=`<span class="status-dot ${s.pending?'amber':'green'}"></span>${s.pending?'Agent 正在回复 · 后台任务继续':'Agent 就绪 · 可继续讨论'}`;
    renderChips();scroll.scrollTop=scrollBottom?scroll.scrollHeight:position;
  }
  function renderChips(){$('#context-chips').innerHTML=session().refs.map(r=>`<span class="context-chip">↗ ${e(refNames[r]||r)}<button data-action="remove-ref" data-ref="${e(r)}" aria-label="移除引用 ${e(refNames[r]||r)}">×</button></span>`).join('');}
  function chart(){return `<svg class="chart" viewBox="0 0 320 155" role="img" aria-label="固定演示曲线：训练损失从约 2.4 下降到 0.842"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--brand)" stop-opacity=".14"/><stop offset="1" stop-color="var(--brand)" stop-opacity="0"/></linearGradient></defs>${[25,65,105].map((y,i)=>`<line x1="26" x2="310" y1="${y}" y2="${y}"/><text x="0" y="${y+3}">${['2.4','1.6','0.8'][i]}</text>`).join('')}<path fill="url(#area)" d="M28 28L48 55L68 70L88 65L108 81L128 86L148 89L168 94L188 91L208 101L228 99L248 105L268 108L288 109L306 114V130H28Z"/><path class="baseline" d="M28 30L68 71L108 81L148 89L188 92L228 95L268 97L306 98"/><path class="loss" d="M28 28L48 55L68 70L88 65L108 81L128 86L148 89L168 94L188 91L208 101L228 99L248 105L268 108L288 109L306 114"/><circle cx="306" cy="114" r="3" fill="var(--brand)"/><text x="25" y="146">0</text><text x="142" y="146">600</text><text x="280" y="146">1,200</text></svg>`;}
  const syncLine=()=>`<div class="sync-line"><span class="status-dot ${state.connected?'green':'amber'}"></span>${state.connected?'最后同步 14:32:08 · 固定演示快照':'连接中断 · 最后观测 14:32:08，数据已过期'}</div>`;
  function trainInspector(){
    const sub=state.inspector.sub||'metrics';
    return `<div class="section-title"><h3>当前观察对象</h3>${button('任务列表','run-list','text')}</div><div class="object-heading"><span class="card-icon">⌁</span><div><h3>长尾样本增强实验</h3><small>Run-042 · job_042 · gpu-a100-01</small></div></div><div class="row between">${badge(statusLabel(state.train.status),state.train.status==='running'?'green':state.train.status==='pending'?'amber':'neutral')}<span class="muted small-text">Qwen3-8B · LoRA SFT</span></div>${syncLine()}${!state.connected?'<div class="alert">远端可能仍在运行。恢复连接后对账，不推断任务失败。</div>':''}<div class="subtabs" role="tablist">${[['metrics','指标'],['logs','日志'],['checkpoints','检查点'],['config','配置']].map(([id,name])=>`<button role="tab" aria-selected="${sub===id}" class="${sub===id?'active':''}" data-action="run-tab" data-tab="${id}">${name}</button>`).join('')}</div>`+
      (sub==='metrics'?`<div class="surface-card"><div class="section-title"><h3>训练进展</h3><small>${Math.round(state.train.step/30)}%</small></div><div class="metric-row"><div><small>Steps</small><strong>${state.train.step.toLocaleString()}</strong></div><div><small>Loss</small><strong>0.842</strong></div><div><small>验证通过率</small><strong>82.6<small>%</small></strong></div></div>${progress(state.train.step/30)}<div class="row between muted small-text"><span>目标 3,000 steps</span><span>预计 1h 48m · 示例</span></div></div><div class="surface-card"><div class="section-title"><h3>训练损失</h3><small>train/loss</small></div>${chart()}<div class="chart-legend"><span>━ Run-042</span><span>┄ Run-041 · 固定示意曲线</span></div>${button('引用这段指标','quote','text', 'data-ref="train"')}</div><div class="surface-card"><div class="section-title"><h3>GPU 资源</h3><small>2 × A100 80GB</small></div>${[0,1].map(n=>`<div class="gpu"><div class="row between"><strong>GPU ${n}</strong><span>${n?91:94}% 利用率</span></div>${progress(n?91:94)}<small>显存 ${n?'61.4':'62.1'} / 80 GB · ${n?67:68} °C</small></div>`).join('')}</div>`:
      sub==='logs'?`<label class="field-label" for="log-query">搜索日志</label><input class="input" id="log-query" placeholder="例如 loss 或 WARN"><div class="log-mini" id="log-output">${logMarkup('')}</div>${button('引用当前日志片段','quote','', 'data-ref="train"')}`:
      sub==='checkpoints'?`<div class="object-list">${[1200,1000,800].map(n=>`<div class="surface-card"><div class="row between"><strong class="small-text">checkpoint-${n}</strong>${badge('已持久化','green')}</div><p>包含优化器状态 · 恢复将创建新 Run</p>${button('讨论从此处恢复','checkpoint','text',`data-step="${n}"`)}</div>`).join('')}</div>`:
      `<div class="surface-card"><h3>配置与输入血缘</h3><p>基座：Qwen3-8B / revision 8d19a2</p><p>数据：售后数据集 v3 / 配方 r7</p><p>代码：train.py / commit a83f2c1</p><p>运行环境：env-07 · seed 42</p><pre class="code">strategy: lora_sft\nlora_rank: 32\nlearning_rate: 0.00002\nmax_steps: 3000\nseed: 42</pre>${button('引用配置继续讨论','quote','', 'data-ref="config"')}</div>`)+
      `<div class="row between" style="margin-top:15px"><span class="muted small-text">取消操作需远端确认</span>${button('取消训练','cancel-run','danger', ['cancelled','pending','completed'].includes(state.train.status)?'disabled':'')}</div>`;
  }
  const logs=[['14:28:03','INFO','step=1000 loss=0.961'],['14:28:05','INFO','checkpoint-1000 persisted'],['14:29:12','WARN','dataloader latency=420ms'],['14:30:18','INFO','validation pass_rate=0.826'],['14:32:08','INFO','step=1200 loss=0.842'],['14:32:09','INFO','checkpoint-1200 persisted']];
  const logMarkup=q=>logs.filter(l=>l.join(' ').toLowerCase().includes(q.toLowerCase())).map(l=>`<div class="${l[1]==='WARN'?'warn':''}">${l.join(' ')}</div>`).join('')||'没有匹配的日志';
  function evalInspector(){const done=state.eval.scored===1000;return `<div class="section-title"><h3>候选模型评测</h3>${badge(done?'已完成':'评分中',done?'green':'amber')}</div><div class="surface-card"><h3>Eval-018 · 业务评测集 v2</h3><p>生成完成 1,000 / 1,000 · 已评分 ${state.eval.scored} / 1,000</p>${progress(state.eval.scored/10)}<div class="metric-row"><div><small>${done?'最终通过率':'阶段通过率'}</small><strong>${done?'83.1':'82.8'}<small>%</small></strong></div><div><small>对比基线</small><strong>+${done?'4.7':'4.4'}<small>pp</small></strong></div><div><small>业务目标</small><strong>85<small>%</small></strong></div></div></div><div class="alert">${done?'完整评测已结束，仍未达到发布门槛。':'当前分数为阶段结果，不能用于发布准入。'}</div><div class="surface-card"><div class="section-title"><h3>业务场景切片</h3><small>${done?'最终':'阶段'}结果</small></div>${[['退换货',89.2],['物流异常',71.2],['退款时效',86.4],['保修政策',85.6]].map(([title,n])=>`<div class="slice"><div class="row between"><span>${title}</span><strong>${n}%</strong></div>${progress(n)}</div>`).join('')}<p>固定集切片；阶段结果待完整评分确认。</p></div><div class="surface-card"><h3>错误摘要 · E-0041</h3><p>遗漏“已签收未收到”的承运方核查步骤。依据：support-policy-v2 / 条款 3.2。</p><p>补数据任务仅接收失败类别和业务资料来源，不接收测试题目及参考答案。</p>${button('引用错误类别给 Agent','quote','text', 'data-ref="eval"')}</div><div class="row between">${button('查看评分协议','eval-protocol')}${!done?button('完成评分演示','finish-eval','primary'):button('讨论下一轮','discuss-eval','primary')}</div>`;}
  function dataInspector(){const sub=state.inspector.sub||'recipe';return `<div class="object-heading"><span class="card-icon">▤</span><div><h3>售后数据集构建</h3><small>Data-019 · 配方 r7 · 当前 v${state.datasetVersion}</small></div></div><div class="subtabs" role="tablist">${[['recipe','配方'],['sample','样本审核'],['versions','版本血缘']].map(([id,name])=>`<button role="tab" aria-selected="${sub===id}" class="${sub===id?'active':''}" data-action="data-tab" data-tab="${id}">${name}</button>`).join('')}</div>`+(sub==='recipe'?`<div class="surface-card"><h3>构建步骤与状态</h3><div class="checklist">${[['✓','工单与知识库接入','28,640 条 · 来源快照已记录'],['✓','脱敏、格式清洗与去重','24,860 条可用训练记录'],['✓','长尾业务增强','仅使用训练侧业务资料'],[state.retry?'✓':'!','质量审计与分片恢复',state.retry?'分片 17 已重试完成':'分片 17 超时，断点已保存'],[state.sample.status==='待修正'?'○':'✓','人工复核与冻结',state.sample.status==='待修正'?'样本 S-0283 等待确认':'人工审核已处理']].map(([n,title,desc])=>`<div><span class="checkmark">${n}</span><div>${title}<small>${desc}</small></div></div>`).join('')}</div></div><div class="alert">训练、验证与测试资料分别管理。测试答案不用于生成增强数据。</div><div class="row">${button(state.retry?'分片已恢复':'重试失败分片','retry-data','',state.retry?'disabled':'')}${button('审核问题样本','sample','primary')}</div>`:
      sub==='sample'?`<div class="surface-card"><div class="section-title"><h3>S-0283 · 退款时效</h3>${badge(state.sample.status,state.sample.status==='已通过'?'green':'amber')}</div><div class="field-label">用户问题</div><p class="sample-copy">退款后要多久才能到账？</p><label class="field-label" for="sample-answer">候选答案 · 可编辑</label><textarea class="input" id="sample-answer" rows="5">${e(state.sample.answer)}</textarea><div class="alert">“两小时到账”缺少业务依据。请核对支付渠道及售后政策，避免无依据承诺。</div><p>来源：合成数据 batch_019 · 对照资料：退款政策 v2</p><div class="row" style="margin-top:13px">${button('排除样本','exclude-sample','danger')}${button('保存并通过','approve-sample','primary')}</div></div>`:
      `<div class="surface-card"><h3>售后数据集 v${state.datasetVersion}</h3><p>业务工单与知识库快照 → 配方 r7 → 分片审计 → 人工复核 → 冻结版本</p><p>使用记录：Run-041 / Run-042</p><p>后续发布的版本不会修改正在训练的 Run-042 输入。</p></div>${button('冻结新版本','publish-data','primary')}`)+button('引用数据记录给 Agent','quote','text evidence-button','data-ref="data"');}
  function planInspector(){return `<div class="section-title"><h3>Plan-003 · 下一轮验证</h3>${badge(state.plan.submitted?'已提交':'草稿',state.plan.submitted?'green':'neutral')}</div><div class="surface-card"><label for="plan-goal" class="field-label">验证目标</label><textarea id="plan-goal" class="input" rows="2" ${state.plan.submitted?'disabled':''}>${e(state.plan.goal)}</textarea><label for="plan-budget" class="field-label">GPU 预算（小时）</label><input id="plan-budget" class="input" type="number" min="0.5" max="6" step="0.5" value="${state.plan.budget}" ${state.plan.submitted?'disabled':''}><div class="checklist"><div><span class="checkmark">1</span><div>审计业务条件覆盖<small>确认签收争议、超时未揽收等场景</small></div></div><div><span class="checkmark">2</span><div>小规模补数据与单变量训练<small>固定模型与参数，对比长尾权重</small></div></div><div><span class="checkmark">3</span><div>同协议独立评测<small>记录收益、退化切片与资源开销</small></div></div></div><p>停止条件：预算耗尽，或连续 3 次验证不改善。</p><p>成功标准：相同评测协议下，目标切片改善且整体不退化。</p></div><div class="alert good">普通读取、诊断和已授权动作可直接进行。此处的提交卡用于审阅长时任务的目标、范围与预算。</div><div class="row">${button('讨论这个计划','quote','', 'data-ref="plan"')}${button(state.plan.submitted?'查看已提交任务':'提交演示任务',state.plan.submitted?'tasks':'execute-plan','primary')}</div>`;}
  function taskRows(){return [{id:'Data-019',name:'售后数据构建',desc:'配方 r7 · 样本复核',object:'data',status:'review'}, {id:'Run-042',name:'长尾样本增强实验',desc:'gpu-a100-01 · 2 × A100',object:'train',status:state.train.status},{id:'Eval-018',name:'候选模型业务评测',desc:`已评分 ${state.eval.scored} / 1,000`,object:'eval',status:state.eval.scored===1000?'completed':'running'},...state.extras];}
  function tasksMarkup(){return `<div class="object-list">${taskRows().map(t=>`<button class="object-item" data-action="task-object" data-object="${t.object}" data-id="${t.id}"><span class="card-icon">${t.object==='data'?'▤':t.object==='eval'?'☷':'⌁'}</span><div><strong>${e(t.name)}</strong><small>${t.id} · ${e(t.desc)}</small></div>${badge(statusLabel(t.status),t.status==='running'?'green':t.status==='review'||t.status==='pending'?'amber':'neutral')}</button>`).join('')}</div>`;}
  function assetsMarkup(){return `<div class="section-title"><h3>项目资产</h3><small>项目作用域</small></div>${[['data','▤','售后数据集 v'+state.datasetVersion,'来源、配方与审计'],['config','⌘','train.yaml','训练参数与环境快照'],['report','☷','eval-report.md','协议、指标与错误摘要'],['model','◇','售后模型 v3','基座、训练与评测血缘']].map(([id,ic,name,desc])=>`<button class="file-row" data-action="object" data-object="${id}"><span>${ic}</span><div>${name}<small>${desc}</small></div><span>↗</span></button>`).join('')}<div class="alert good">资产属于项目，会话只保存引用。切换会话不会复制数据或重建任务。</div>`;}
  function fileInspector(obj){if(obj==='model')return `<div class="section-title"><h3>售后模型 v3</h3>${badge('稳定版本','green')}</div><div class="surface-card"><div class="checklist"><div><span class="checkmark">◇</span><div>基座 Qwen3-8B<small>固定 revision 8d19a2</small></div></div><div><span class="checkmark">▤</span><div>数据集 v3<small>配方 r7 · 来源快照</small></div></div><div><span class="checkmark">⌁</span><div>Run-041 / checkpoint-3000<small>LoRA · seed 42</small></div></div><div><span class="checkmark">☷</span><div>Eval-017 / 业务评测 v2<small>最终通过率 82.6%</small></div></div></div></div><div class="alert">候选 v4-rc1 尚未达到 85% 门槛，不能正式发布。</div>${button('预览部署与回滚','deployment')}${button('引用模型血缘','quote','text evidence-button','data-ref="model"')}`;
    return `<div class="section-title"><h3>${obj==='config'?'train.yaml':'eval-report.md'}</h3>${badge('只读预览')}</div><pre class="code">${obj==='config'?'run_id: run_042\nbase_model: Qwen3-8B\ndataset: support_v3\nstrategy: lora_sft\nlora_rank: 32\nlearning_rate: 0.00002\nseed: 42':'# 业务评测摘要\nprotocol: support_eval_v2\nsamples: 1000\nscored: '+state.eval.scored+'\nstatus: '+(state.eval.scored===1000?'final':'provisional')+'\nweak_slice: logistics_exception\nrelease_gate: not_passed'}</pre><p class="small-text muted">对象预览与中心会话并存。点击引用后，Agent 才会收到你选定的对象引用。</p>${button('引用到当前输入框','quote','primary evidence-button',`data-ref="${obj}"`)}`;}
  function activityMarkup(){return `<div class="section-title"><h3>项目运行记录</h3><small>状态与会话分开保存</small></div>${state.events.map(ev=>`<button class="object-item" style="margin-bottom:10px" data-action="object" data-object="${ev.object}"><span class="muted small-text">${ev.time}</span><div><strong>${e(ev.text)}</strong><small>查看关联对象 ↗</small></div></button>`).join('')}`;}
  function renderInspector(){
    const i=state.inspector;
    $('#inspector-tabs').innerHTML=[['plan','计划'],['runs','运行'],['assets','资产'],['activity','记录']].map(([id,title])=>`<button class="inspector-tab" role="tab" aria-selected="${i.tab===id}" data-action="inspector-tab" data-tab="${id}">${title}</button>`).join('');
    $('#scope-label').textContent=i.pin?'已固定观察对象':'跟随当前会话';$('#pin-button').classList.toggle('selected',i.pin);$('#pin-button').setAttribute('aria-pressed',String(i.pin));
    let content=i.tab==='plan'?planInspector():i.tab==='activity'?activityMarkup():i.tab==='runs'?(i.object==='train'?trainInspector():i.object==='eval'?evalInspector():tasksMarkup()):i.object==='data'?dataInspector():['config','report','model'].includes(i.object)?fileInspector(i.object):assetsMarkup();
    const owner=state.sessions.find(s=>s.id===i.owner)?.title||'项目';
    $('#inspector-body').innerHTML=(i.pin?`<div class="pin-banner">已固定：${e(refNames[i.object]||'任务列表')}<br>来自会话「${e(owner)}」· 切换会话继续观察</div>`:'')+content;
  }
  function updateFooter(){const active=taskRows().filter(t=>!['cancelled','completed'].includes(t.status)).length;$('#task-count').textContent=active;$('#footer-tasks').textContent=active+' 个后台任务';$('#connection-label').textContent=state.connected?'◉ 算力已连接':'◉ 连接中断';$('#footer-connection').textContent=state.connected?'SSH 已连接 · 模拟':'连接中断 · 点击恢复';$('#footer-dot').className='status-dot '+(state.connected?'green':'amber');}
  function render(){renderSidebar();renderCenter();renderInspector();updateFooter();state.rightOpen=!$('#app').classList.contains('right-hidden')&&(window.innerWidth>1050||$('#inspector').classList.contains('mobile-open'));$('.workbench-toggle').setAttribute('aria-expanded',String(state.rightOpen));}
  function quote(ref){if(!session().refs.includes(ref))session().refs.push(ref);renderChips();$('#prompt').focus();showToast('已引用到当前会话；发送后 Agent 才会收到引用');}
  function response(text,refs){
    if(/只有业务|少量业务|业务要求/.test(text))return {text:'【演示】先描述典型输入、期望输出和不可接受的错误。我会和你建立一批可人工判定的验收样本，跑开源模型基线，再判断应使用提示、检索还是微调。没有模型、数据或复现目标，也可以从这里开始。',refs:[],card:'plan'};
    if(/数据|审核|清洗/.test(text)||refs.includes('data'))return {text:'【演示】当前 Data-019 保留了配方与分片断点。先修正或排除 S-0283，再重试失败分片，审核完成后冻结新版本。新版本不会修改 Run-042 已绑定的输入。',refs:['data'],card:'data'};
    if(/评测|物流|分数|错误/.test(text)||refs.includes('eval')||refs.includes('report'))return {text:'【演示】物流异常切片目前为 71.2%。先核对签收争议的业务规则覆盖，再根据失败类别补充训练侧资料。测试题目与参考答案继续隔离；评测完成前不使用阶段分数判断发布。',refs:['eval'],card:'plan'};
    if(/恢复|loss|日志|训练/.test(text)||refs.includes('train'))return {text:'【演示】Run-042 最近 loss 为 0.842，尚无发散证据。一次数据加载延迟警告不足以认定 GPU 瓶颈。先结合吞吐与后续日志观察，最终业务收益由独立评测判断。远端任务继续运行，和当前回复互不影响。',refs:['train'],card:'train'};
    return {text:'【演示】我会把这个方向整理为可验证的假设：明确成功标准、固定评测协议、只改变一个变量，并设定资源预算。右侧可以调整计划；如果先探索检索或数据规则，也可以继续在当前会话中讨论。',refs:['plan'],card:'plan'};
  }
  function send(text){
    const s=session();if(s.pending){stopAgent();return;}if(!text.trim())return;
    const refs=[...s.refs],engine=state.engine;s.messages.push({role:'user',text:text.trim(),refs});s.refs=[];s.draft='';s.pending=true;s.pendingEngine=engine;renderSidebar();renderCenter(true);
    const id=s.id;state.timers[id]=setTimeout(()=>{const target=state.sessions.find(x=>x.id===id);if(!target||!target.pending)return;target.pending=false;target.messages.push({role:'agent',engine,...response(text,refs)});delete state.timers[id];renderSidebar();if(state.current===id)renderCenter(true);},850);
  }
  function stopAgent(){const s=session();clearTimeout(state.timers[s.id]);delete state.timers[s.id];s.pending=false;s.messages.push({role:'agent',text:'Agent 回复已停止。远端训练、数据构建与评测仍保持各自任务状态。',refs:[]});renderSidebar();renderCenter(true);showToast('已停止当前 Agent 回复，未取消后台任务');}
  function persistPlan(){const goal=$('#plan-goal'),budget=$('#plan-budget');if(goal&&!state.plan.submitted){const n=Number(budget.value);if(!goal.value.trim()||!Number.isFinite(n)||n<0.5||n>6){showToast('请填写目标，GPU 预算需在 0.5–6 小时之间');return false;}state.plan.goal=goal.value.trim();state.plan.budget=n;}return true;}
  function commitPlan(){if(state.plan.submitted){showToast('此计划已提交，不重复创建任务');return;}state.plan.submitted=true;state.extras.push({id:'Run-043',name:'下一轮单变量验证',desc:`${state.plan.budget} GPU·h · 等待资源`,object:'extra',status:'queued'});event('Plan-003 已提交为 Run-043，任务排队中。','extra');const s=session();s.messages.push({role:'agent',text:'【演示】已收到本轮计划，任务 Run-043 已进入演示队列，状态为排队中。尚未启动真实训练。',refs:['plan']});render();showToast('已创建 Run-043 演示任务 · 不占用真实 GPU');}
  const actions={
    session:el=>selectSession(el.dataset.id),object:el=>openObject(el.dataset.object),
    'toggle-left'(){if(window.innerWidth<=720)$('#app').classList.toggle('mobile-left');else $('#app').classList.toggle('left-hidden');},
    'toggle-right'(){if(window.innerWidth<=1050){const open=$('#inspector').classList.contains('mobile-open');$('#inspector').classList.toggle('mobile-open',!open);$('#app').classList.remove('right-hidden');state.rightOpen=!open;}else{state.rightOpen=!state.rightOpen;$('#app').classList.toggle('right-hidden',!state.rightOpen);}$('.workbench-toggle').setAttribute('aria-expanded',String(state.rightOpen));},
    'expand-right'(){setWidth(state.width>430?390:580);},
    pin(){state.inspector.pin=!state.inspector.pin;renderInspector();showToast(state.inspector.pin?'已固定右侧观察对象，切换会话将保留':'已解除固定，后续切换会话将跟随其上下文');},
    'inspector-tab'(el){if(state.inspector.tab==='plan'&&!persistPlan())return;const tab=el.dataset.tab;state.inspector.tab=tab;state.inspector.object=tab==='runs'?'tasks':tab==='assets'?'assets':tab;session().context={tab,object:state.inspector.object,sub:''};renderInspector();},
    'run-tab'(el){state.inspector.sub=el.dataset.tab;session().context={tab:'runs',object:'train',sub:el.dataset.tab};renderInspector();},'data-tab'(el){if(state.inspector.sub==='sample'&&$('#sample-answer'))state.sample.answer=$('#sample-answer').value;state.inspector.sub=el.dataset.tab;session().context={tab:'assets',object:'data',sub:el.dataset.tab};renderInspector();},
    'run-list'(){state.inspector.object='tasks';renderInspector();},
    'task-object'(el){close();if(el.dataset.object==='extra'){state.inspector.tab='runs';state.inspector.object='tasks';showRight();renderInspector();showToast('Run-043 正在演示队列中，尚未开始训练');}else openObject(el.dataset.object);},
    quote:el=>quote(el.dataset.ref),
    'remove-ref'(el){session().refs=session().refs.filter(x=>x!==el.dataset.ref);renderChips();},
    'inspect-logs'(){openObject('train','logs');},'inspect-eval'(){openObject('eval');},sample(){close();openObject('data','sample');},
    'approve-sample'(){const text=$('#sample-answer').value.trim();if(!text){showToast('请先填写答案');return;}state.sample.answer=text;state.sample.status='已通过';event('S-0283 已由用户审核通过，记录本地演示审计。','data');saveDraft();render();showToast('答案已保存，样本已通过（本地演示）');},
    'exclude-sample'(){state.sample.answer=$('#sample-answer').value;state.sample.status='已排除';event('S-0283 已从候选训练数据排除。','data');saveDraft();render();showToast('该样本已排除，原始记录仍保留');},
    'retry-data'(){state.retry=true;event('Data-019 分片 17 重试完成，复用其余步骤断点。','data');renderInspector();showToast('失败分片已恢复 · 其余步骤未重复运行（演示）');},
    'publish-data'(){if(state.sample.status==='待修正'||!state.retry){showToast('请先处理问题样本，并重试失败分片');return;}state.datasetVersion++;event('售后数据集 v'+state.datasetVersion+' 已冻结，未修改现有训练输入。','data');renderSidebar();renderInspector();showToast('已冻结数据集 v'+state.datasetVersion+' · 本地演示');},
    'cancel-run'(){modal('取消 Run-042 训练？',`<p>取消目标：<strong>job_042 / gpu-a100-01</strong></p><p>已保存的 checkpoint 保留。该操作独立于停止 Agent 回复。</p>${!state.connected?'<div class="alert">当前连接中断；记录取消意图，重连后等待远端确认。</div>':'<div class="alert">本原型将演示远端确认，不操作真实服务器。</div>'}`,button('继续训练','close')+button('确认取消训练','confirm-cancel','danger'));},
    'confirm-cancel'(){state.train.status=state.connected?'cancelled':'pending';event(state.connected?'Run-042 已获得远端取消确认（演示）。':'Run-042 取消请求待确认，等待恢复连接。');close();saveDraft();render();showToast(statusLabel(state.train.status)+' · 本地演示');},
    connection(){state.connected=!state.connected;if(state.connected&&state.train.status==='pending'){state.train.status='cancelled';event('重连对账：Run-042 已获得远端取消确认。');}else event(state.connected?'连接恢复，任务状态、日志与指标游标已对账（演示）。':'连接中断，保留最后观测值；远端任务可能继续。');saveDraft();render();showToast(state.connected?'连接恢复，已完成演示状态对账':'连接中断，显示最后观测，不推断训练失败');},
    'finish-eval'(){state.eval.scored=1000;event('Eval-018 最终通过率 83.1%，未满足发布门槛。','eval');renderInspector();updateFooter();showToast('评分演示完成：最终 83.1%，仍低于 85% 目标');},
    'discuss-eval'(){quote('eval');send('请分析最终评测，并提出下一轮策略。');},
    'eval-protocol'(){modal('业务评测协议 v2','<p>固定集 1,000 条，覆盖退换货、物流异常、退款时效与保修政策。</p><div class="surface-card"><p>评分：规则检查 + 固定版本模型裁判 + 人工抽检。</p><p>基线与候选使用同一协议；保存输入摘要、裁判设置、评分输出与复核记录。</p><p>阶段结果与最终结果分别标识。测试题目、参考答案与训练资料隔离。</p></div>',button('关闭','close'));},
    checkpoint(el){quote('train');$('#prompt').value=`请评估从 checkpoint-${el.dataset.step} 恢复的必要性，创建新 Run 前说明配置差异和预算。`;session().draft=$('#prompt').value;},
    'execute-plan'(){if(state.plan.submitted){actions.tasks();return;}if(!persistPlan())return;modal('提交下一轮演示任务',`<p><strong>${e(state.plan.goal)}</strong></p><div class="surface-card"><p>预算：${state.plan.budget} GPU·h · 模型：Qwen3-8B</p><p>输入：审核后的数据版本 · 固定评测协议 v2</p><p>单变量验证；预算耗尽或连续 3 次验证不改善时停止。</p></div><p>此按钮只创建本地演示队列，不实际调用 Harness 或 GPU。</p>`,button('继续讨论','close')+button('提交演示任务','commit-plan','primary'));},
    'commit-plan'(){close();saveDraft();commitPlan();},
    tasks(){modal('后台任务 · 当前项目',`<p>项目任务独立于会话，当前会话不变。点击任意任务，在右侧查看其记录。</p>${tasksMarkup()}`,button('关闭','close'));},
    'new-session'(){saveDraft();const id='session-'+(state.sessions.length+1);state.sessions.unshift({id,title:'新的研究会话',summary:'刚刚 · 从业务或想法开始',kind:'new',engine:state.engine,context:{tab:'plan',object:'plan',sub:''},messages:[],draft:'',refs:[],pending:false});selectSession(id);},
    starter(el){send(el.dataset.text);},
    projects(){modal('项目与工作上下文','<p>当前项目：售后服务模型。会话、任务和资产都属于项目，但各自具有独立身份与生命周期。</p><div class="mode-grid">'+[['冲榜优化','模型 + 数据 + 明确评测'],['业务适配','模型 + 少量业务数据'],['从业务开始','只有场景与业务目标'],['开放研究','方向、假设与训练策略']].map(([title,desc])=>`<button class="mode-button" data-action="project-mode" data-text="${title}"><strong>${title}</strong><small>${desc}</small></button>`).join('')+'</div>',button('关闭','close'));},
    'project-mode'(el){close();actions['new-session']();send('我想以“'+el.dataset.text+'”模式开始，请先帮我澄清目标。');},
    'reference-menu'(){modal('引用项目上下文',`<p>只向当前会话添加明确选定的对象引用；不会因为打开右侧面板而自动发送整份数据。</p>${Object.entries(refNames).map(([id,name])=>`<button class="object-item" data-action="select-ref" data-ref="${id}"><span class="card-icon">↗</span><div><strong>${name}</strong><small>点击加入当前输入框</small></div></button>`).join('')}`,button('关闭','close'));},
    'select-ref'(el){close();quote(el.dataset.ref);},
    attach(){modal('添加上下文附件','<p>原型只展示文件名，不读取或上传文件内容。</p><input class="input" id="attachment" type="file" multiple><p id="attachment-label" class="muted small-text" style="margin-top:10px">选择业务资料、配置或研究笔记</p>',button('取消','close')+button('加入引用','attach-files','primary'));},
    'attach-files'(){const files=$('#attachment').files;if(!files.length){showToast('请先选择文件');return;}for(const f of files){const name='附件：'+f.name;if(!session().refs.includes(name))session().refs.push(name);}close();renderChips();showToast('只添加了文件名引用，未读取或上传内容');},
    engine(){modal('选择 Harness 引擎','<p>会话交互保持统一，实际模型、工具与权限能力由对应引擎适配器声明。</p><div class="mode-grid">'+['Codex','Claude Code','OpenCode','DeepSeek Harness'].map(name=>`<button class="mode-button ${state.engine===name?'engine-selected':''}" data-action="select-engine" data-engine="${name}"><strong>${name}</strong><small>${state.engine===name?'当前演示引擎':'切换演示配置'}</small></button>`).join('')+'</div><div class="alert">切换仅更新原型配置，不启动真实进程。正式产品应在下一回合使用新引擎，并记录运行身份。</div>',button('关闭','close'));},
    'select-engine'(el){state.engine=el.dataset.engine;$('#engine-name').textContent=state.engine;close();showToast('下一回合使用 '+state.engine+'（演示）');},
    policy(){modal('项目授权与人工决策','<p>普通资料读取、诊断和已授权任务不逐步打断。需要人工判断的业务问题与引擎原生权限请求分开呈现。</p><div class="surface-card"><h3>本原型</h3><p>所有执行按钮都只影响本地演示状态；不授予真实工具、网络或服务器权限。</p></div><div class="surface-card"><h3>正式产品的权限卡片</h3><p>展示具体动作、目标主机、作用域及原生请求 ID；按引擎能力回答，结果进入会话事件记录。</p></div>',button('关闭','close'));},
    extensions(){modal('Skills 与 MCP · 项目作用域',`<p>扩展入口放在左侧项目设置中；执行时在中心会话显示工具活动与结果。</p>${[['data','数据构建 Skill','配方、质量审计与断点'],['training','训练执行 Skill','参数检查与远端提交'],['mcp','研究检索 MCP','只读资料检索']].map(([id,name,desc])=>`<div class="surface-card row between"><div><h3>${name}</h3><p>${desc}</p></div><button class="switch ${state.extensions[id]?'on':''}" role="switch" aria-checked="${state.extensions[id]}" aria-label="启用 ${name}" data-action="extension-toggle" data-key="${id}"></button></div>`).join('')}<div class="alert">仅更改演示开关，不启动实际工具或服务。</div>`,button('关闭','close'));},
    'extension-toggle'(el){state.extensions[el.dataset.key]=!state.extensions[el.dataset.key];actions.extensions();},
    attention(){modal('待处理事项','<p>业务决策进入会话；故障与运行状态进入任务记录。不会因为通知而替换当前聊天。</p><button class="object-item" data-action="sample"><span class="card-icon">!</span><div><strong>审核退款时效样本</strong><small>S-0283 · 缺少事实依据</small></div>'+badge(state.sample.status,'amber')+'</button><button class="object-item" data-action="attention-eval"><span class="card-icon">☷</span><div><strong>检查评测准入</strong><small>完整评测与关键切片均需满足目标</small></div></button>',button('关闭','close'));},
    'attention-eval'(){close();openObject('eval');},
    'session-info'(){modal('会话与项目的关系',`<p>当前会话：${e(session().title)}</p><p>会话负责目标讨论、工具活动和人工决策。Run-042、数据集和评测属于项目，切换或关闭会话不取消远端任务。</p><div class="surface-card"><p>右侧“跟随”：切换会话时恢复其观察对象。</p><p>右侧“固定”：跨会话保留当前任务监控。</p><p>打开对象不等于加入 Agent 上下文；使用“引用”显式带入下一条消息。</p></div>`,button('关闭','close'));},
    deployment(){modal('部署与回滚预览','<div class="alert">候选模型未达到发布门槛。此处仅预览稳定版的沙箱流程。</div><div class="checklist"><div><span class="checkmark">✓</span>稳定版本与权重血缘已关联</div><div><span class="checkmark">○</span>创建候选服务与健康检查</div><div><span class="checkmark">○</span>冒烟测试、灰度和版本路由</div><div><span class="checkmark">○</span>保留上一稳定版本作为回滚点</div></div><p>未启动真实推理服务或创建网络端点。</p>',button('关闭','close')+button('模拟回滚','rollback'));},
    rollback(){close();event('部署预览：已演示恢复上一稳定版本路由。','model');showToast('沙箱回滚预览完成 · 未操作真实服务');},
    search(){modal('搜索会话、任务与项目资产','<input id="search-input" class="input" placeholder="例如：物流、Run-042 或数据" aria-label="搜索工作区"><div id="search-results">'+searchMarkup('')+'</div>',button('关闭','close'));$('#search-input').focus();},
    'search-result'(el){close();if(el.dataset.kind==='session')selectSession(el.dataset.target);else openObject(el.dataset.target);},
    theme(){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';},close,
    'stop-agent':stopAgent
  };
  function searchMarkup(query){const items=[...state.sessions.map(s=>({kind:'session',id:s.id,title:s.title,desc:'项目会话'})),...Object.entries(refNames).map(([id,title])=>({kind:'object',id,title,desc:'项目对象 · 在右侧打开'}))].filter(x=>(x.title+' '+x.desc).toLowerCase().includes(query.toLowerCase()));return items.map(x=>`<button class="object-item" data-action="search-result" data-kind="${x.kind}" data-target="${x.id}"><span class="card-icon">${x.kind==='session'?'◷':'↗'}</span><div><strong>${e(x.title)}</strong><small>${x.desc}</small></div></button>`).join('')||'<p class="muted small-text" style="padding:20px">没有匹配结果</p>';}
  function setWidth(value){const sidebar=$('#app').classList.contains('left-hidden')?0:$('#sidebar').getBoundingClientRect().width;const max=Math.max(330,Math.min(620,window.innerWidth-sidebar-470));state.width=Math.max(330,Math.min(value,max));document.documentElement.style.setProperty('--panel-width',state.width+'px');$('#splitter').setAttribute('aria-valuenow',String(state.width));$('#splitter').setAttribute('aria-valuemax',String(max));}
  document.addEventListener('click',ev=>{const el=ev.target.closest('button[data-action]');if(el&&!el.disabled)actions[el.dataset.action]?.(el);});
  document.addEventListener('submit',ev=>{if(ev.target.id==='composer-form'){ev.preventDefault();send($('#prompt').value);}});
  document.addEventListener('input',ev=>{if(ev.target.id==='prompt')session().draft=ev.target.value;if(ev.target.id==='log-query')$('#log-output').innerHTML=logMarkup(ev.target.value);if(ev.target.id==='search-input')$('#search-results').innerHTML=searchMarkup(ev.target.value);if(ev.target.id==='sample-answer')state.sample.answer=ev.target.value;});
  document.addEventListener('change',ev=>{if(ev.target.id==='attachment')$('#attachment-label').textContent=Array.from(ev.target.files).map(f=>f.name).join('、')||'未选择文件';if(['plan-goal','plan-budget'].includes(ev.target.id))persistPlan();});
  document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();actions.search();}if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='n'&&!ev.altKey){ev.preventDefault();actions['new-session']();}if(ev.target.id==='prompt'&&ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing){ev.preventDefault();send(ev.target.value);}if(ev.key==='Escape'&&!$('#modal').open){$('#inspector').classList.remove('mobile-open');$('#app').classList.remove('mobile-left');}if(ev.target.id==='splitter'&&['ArrowLeft','ArrowRight','Home'].includes(ev.key)){ev.preventDefault();setWidth(ev.key==='Home'?390:state.width+(ev.key==='ArrowLeft'?20:-20));}});
  $('#splitter').addEventListener('pointerdown',ev=>{if(window.innerWidth<=1050)return;ev.preventDefault();const start=ev.clientX,width=state.width,el=ev.currentTarget;el.setPointerCapture(ev.pointerId);const move=x=>setWidth(width+start-x.clientX);const end=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',end);};el.addEventListener('pointermove',move);el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);});
  $('#splitter').addEventListener('dblclick',()=>setWidth(390));
  window.addEventListener('resize',()=>{if(window.innerWidth>1050)setWidth(state.width);state.rightOpen=!$('#app').classList.contains('right-hidden')&&(window.innerWidth>1050||$('#inspector').classList.contains('mobile-open'));$('.workbench-toggle').setAttribute('aria-expanded',String(state.rightOpen));});
  $('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)close();}});
  if(window.innerWidth>1050)setWidth(state.width);
  render();
})();
